ALTER TABLE public.circles ADD COLUMN owner_id uuid REFERENCES public.profiles(id), ADD COLUMN type text NOT NULL DEFAULT 'Class', ADD COLUMN description text NOT NULL DEFAULT '', ADD COLUMN photo_url text NOT NULL DEFAULT '', ADD COLUMN general_area text NOT NULL DEFAULT '', ADD COLUMN join_rule text NOT NULL DEFAULT 'invite_only', ADD COLUMN email_domain text, ADD COLUMN members_can_invite boolean NOT NULL DEFAULT true;
UPDATE public.circles SET email_domain=required_email_domain;
ALTER TABLE public.circle_members ADD COLUMN role text NOT NULL DEFAULT 'member', ADD COLUMN status text NOT NULL DEFAULT 'active';
ALTER TABLE public.circle_members ADD CONSTRAINT membership_role CHECK(role IN ('owner','member')), ADD CONSTRAINT membership_status CHECK(status IN ('active','pending'));
ALTER TABLE public.profiles ADD COLUMN bio text NOT NULL DEFAULT '', ADD COLUMN general_area text NOT NULL DEFAULT '';
CREATE TABLE public.item_circles(item_id uuid NOT NULL REFERENCES public.items(id) ON DELETE CASCADE,circle_id uuid NOT NULL REFERENCES public.circles(id),position integer NOT NULL DEFAULT 0,PRIMARY KEY(item_id,circle_id));
GRANT SELECT ON public.item_circles TO authenticated; GRANT ALL ON public.item_circles TO service_role;
ALTER TABLE public.item_circles ENABLE ROW LEVEL SECURITY;
INSERT INTO public.item_circles(item_id,circle_id) SELECT id,circle_id FROM public.items;
CREATE OR REPLACE FUNCTION public.is_member(c uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.circle_members WHERE circle_id=c AND user_id=auth.uid() AND status='active') $$;
CREATE FUNCTION public.has_item_access(item uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.item_circles ic JOIN public.circle_members cm ON cm.circle_id=ic.circle_id WHERE ic.item_id=item AND cm.user_id=auth.uid() AND cm.status='active') $$;
REVOKE ALL ON FUNCTION public.has_item_access(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.has_item_access(uuid) TO authenticated;
CREATE POLICY own_item_circles ON public.item_circles FOR SELECT TO authenticated USING(public.has_item_access(item_id));
ALTER POLICY circle_items ON public.items USING(public.has_item_access(id));
ALTER POLICY participants_claims ON public.claims USING(public.has_item_access(item_id) AND (receiver_id=auth.uid() OR EXISTS(SELECT 1 FROM public.items i WHERE i.id=item_id AND i.giver_id=auth.uid())));
ALTER POLICY own_notifications ON public.notifications USING(user_id=auth.uid() AND (item_id IS NULL OR public.has_item_access(item_id)));
ALTER POLICY own_watchers ON public.item_watchers USING(user_id=auth.uid() AND public.has_item_access(item_id));
ALTER POLICY own_passes ON public.swipe_passes USING(user_id=auth.uid() AND public.has_item_access(item_id));
CREATE FUNCTION public.link_primary_circle() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.item_circles(item_id,circle_id) VALUES(NEW.id,NEW.circle_id) ON CONFLICT DO NOTHING; RETURN NEW; END $$;
CREATE TRIGGER link_primary_circle AFTER INSERT ON public.items FOR EACH ROW EXECUTE FUNCTION public.link_primary_circle();
CREATE TRIGGER item_circles_match AFTER INSERT OR UPDATE OR DELETE ON public.item_circles FOR EACH STATEMENT EXECUTE FUNCTION public.recalculate_matches();
CREATE TRIGGER membership_status_match AFTER UPDATE ON public.circle_members FOR EACH STATEMENT EXECUTE FUNCTION public.recalculate_matches();
CREATE FUNCTION public.safe_general_area(t text) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT length(t)<=80 AND t !~ '[0-9]' AND t !~* '\m(apt|apartment|unit|suite)\M' $$;
CREATE FUNCTION public.circle_detail_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.name=public.clean_text(NEW.name); NEW.description=public.clean_text(NEW.description); NEW.general_area=public.clean_text(NEW.general_area); NEW.email_domain=nullif(lower(trim(both '@' FROM trim(coalesce(NEW.email_domain,'')))),''); IF length(NEW.name) NOT BETWEEN 1 AND 50 OR length(NEW.description)>200 THEN RAISE EXCEPTION 'Use a name up to 50 characters and description up to 200'; END IF; IF NOT public.safe_general_area(NEW.general_area) THEN RAISE EXCEPTION 'Use a neighborhood or landmark, not an address'; END IF; IF NEW.join_rule NOT IN('open','request','invite_only') OR NEW.type NOT IN('Class','Friend group','Building or street','Club or team','Workplace','Other') THEN RAISE EXCEPTION 'Choose a circle type and join rule'; END IF; IF NEW.email_domain IS NOT NULL AND NEW.email_domain !~ '^[a-z0-9.-]+\.[a-z]{2,}$' THEN RAISE EXCEPTION 'Enter an email domain, such as berkeley.edu'; END IF; IF OLD.required_email_domain IS NOT NULL AND NEW.email_domain IS DISTINCT FROM OLD.required_email_domain THEN RAISE EXCEPTION 'The existing circle email rule cannot be changed'; END IF; RETURN NEW; END $$;
CREATE TRIGGER circle_details_safe BEFORE INSERT OR UPDATE ON public.circles FOR EACH ROW EXECUTE FUNCTION public.circle_detail_guard();
CREATE FUNCTION public.profile_detail_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.bio=public.clean_text(NEW.bio); NEW.general_area=public.clean_text(NEW.general_area); IF length(NEW.bio)>200 OR NOT public.safe_general_area(NEW.general_area) THEN RAISE EXCEPTION 'Use a short bio and a general area, not an address'; END IF; RETURN NEW; END $$;
CREATE TRIGGER profile_details_safe BEFORE INSERT OR UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.profile_detail_guard();
CREATE OR REPLACE FUNCTION public.member_eligibility() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE domain text; test boolean; email text; BEGIN SELECT coalesce(required_email_domain,email_domain),is_test INTO domain,test FROM public.circles WHERE id=NEW.circle_id; IF test AND NOT public.is_admin() THEN RAISE EXCEPTION 'Only an admin can add test-circle members'; END IF; IF domain IS NOT NULL THEN SELECT u.email INTO email FROM auth.users u WHERE u.id=NEW.user_id AND u.email_confirmed_at IS NOT NULL; IF email IS NULL OR lower(split_part(email,'@',2))<>lower(domain) THEN RAISE EXCEPTION 'Sign in with a verified @% email to join this circle',domain; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER circle_update_eligibility BEFORE UPDATE OF status ON public.circle_members FOR EACH ROW EXECUTE FUNCTION public.member_eligibility();
ALTER TABLE public.events DROP CONSTRAINT events_name_check;
ALTER TABLE public.events ADD CONSTRAINT events_name_check CHECK(name IN('circle_link_opened','item_link_opened','signed_up','joined_circle','wish_added','item_posted','post_nudge_shown','item_shared','match_created','match_notification_sent','swipe_right','swipe_left','item_claimed','pickup_arranged','picked_up','thanked','claim_expired','item_expired','item_renewed','item_marked_donated','notify_me_tapped','clearout_interest_yes','clearout_interest_no','circle_created','circle_search_opened','circle_join_requested','circle_join_approved','circle_joined_from_search','circle_left','member_removed'));
CREATE FUNCTION public.circle_members_detail(circle uuid) RETURNS TABLE(id uuid,display_name text,avatar_url text,bio text,general_area text,joined_at timestamptz,role text,status text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.display_name,p.avatar_url,p.bio,p.general_area,cm.joined_at,cm.role,cm.status FROM public.circle_members cm JOIN public.profiles p ON p.id=cm.user_id JOIN public.circles c ON c.id=cm.circle_id WHERE cm.circle_id=circle AND public.is_member(circle) AND (cm.status='active' OR c.owner_id=auth.uid() OR public.is_admin()) $$;
REVOKE ALL ON FUNCTION public.circle_members_detail(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.circle_members_detail(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.member_names(circle uuid) RETURNS TABLE(id uuid,display_name text,avatar_url text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.display_name,p.avatar_url FROM public.profiles p JOIN public.circle_members cm ON cm.user_id=p.id WHERE cm.circle_id=circle AND cm.status='active' AND public.is_member(circle) $$;
CREATE FUNCTION public.my_circles() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(to_jsonb(c)||jsonb_build_object('invite_token',CASE WHEN c.owner_id=auth.uid() OR c.members_can_invite OR public.is_admin() THEN c.invite_token ELSE NULL END,'my_role',CASE WHEN c.owner_id=auth.uid() THEN 'owner' ELSE 'member' END,'member_count',(SELECT count(*) FROM public.circle_members m WHERE m.circle_id=c.id AND m.status='active')) ORDER BY c.created_at),'[]') FROM public.circles c WHERE public.is_member(c.id) $$;
CREATE FUNCTION public.find_circles() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; RETURN (SELECT coalesce(jsonb_agg(jsonb_build_object('id',c.id,'name',c.name,'type',c.type,'description',c.description,'general_area',c.general_area,'photo_url',c.photo_url,'join_rule',c.join_rule,'email_domain',coalesce(c.required_email_domain,c.email_domain),'member_count',(SELECT count(*) FROM public.circle_members m WHERE m.circle_id=c.id AND m.status='active'),'membership_status',(SELECT m.status FROM public.circle_members m WHERE m.circle_id=c.id AND m.user_id=auth.uid()))),'[]') FROM public.circles c WHERE c.join_rule IN('open','request') AND NOT c.is_test); END $$;
REVOKE ALL ON FUNCTION public.my_circles(),public.find_circles() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.my_circles(),public.find_circles() TO authenticated;
REVOKE SELECT ON public.circles FROM authenticated;
GRANT SELECT(id,name,created_at,is_test,required_email_domain,owner_id,type,description,photo_url,general_area,join_rule,email_domain,members_can_invite) ON public.circles TO authenticated;
CREATE FUNCTION public.circle_action(action text,payload jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u uuid=auth.uid(); cid uuid; target uuid; c public.circles; result jsonb; rule text; BEGIN IF u IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF;
IF action='search_opened' THEN INSERT INTO public.events(user_id,name) VALUES(u,'circle_search_opened'); RETURN '{}'; END IF;
IF action='create' THEN PERFORM 1 FROM public.profiles WHERE id=u FOR UPDATE; IF (SELECT count(*) FROM public.circles WHERE owner_id=u)>=5 THEN RAISE EXCEPTION 'You can own up to 5 circles'; END IF; IF coalesce(payload->>'general_area','')='' THEN RAISE EXCEPTION 'Choose a general area'; END IF;
IF coalesce(payload->>'photo_url','')<>'' AND NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='item-photos' AND name=payload->>'photo_url' AND (storage.foldername(name))[1]=u::text) THEN RAISE EXCEPTION 'Upload your own circle photo first'; END IF;
INSERT INTO public.circles(name,owner_id,type,description,photo_url,general_area,join_rule,email_domain,members_can_invite) VALUES(payload->>'name',u,coalesce(payload->>'type','Other'),coalesce(payload->>'description',''),coalesce(payload->>'photo_url',''),payload->>'general_area',coalesce(payload->>'join_rule','invite_only'),payload->>'email_domain',coalesce((payload->>'members_can_invite')::boolean,true)) RETURNING id INTO cid; INSERT INTO public.circle_members(circle_id,user_id,role) VALUES(cid,u,'owner'); INSERT INTO public.events(user_id,circle_id,name) VALUES(u,cid,'circle_created'); RETURN jsonb_build_object('id',cid); END IF;
IF action='invite_join' THEN SELECT * INTO c FROM public.circles WHERE invite_token=(payload->>'token')::uuid FOR UPDATE; ELSE SELECT * INTO c FROM public.circles WHERE id=(payload->>'circle_id')::uuid FOR UPDATE; END IF; IF c.id IS NULL THEN RAISE EXCEPTION 'This invite is not valid'; END IF; cid=c.id;
IF action IN('join','invite_join') THEN IF c.is_test THEN RAISE EXCEPTION 'Only an admin can add test-circle members'; END IF; IF action='join' AND c.join_rule='invite_only' THEN RAISE EXCEPTION 'Use an invite link for this circle'; END IF; IF public.is_member(cid) THEN RETURN jsonb_build_object('id',cid,'status','active'); END IF; rule=CASE WHEN c.join_rule='request' THEN 'pending' ELSE 'active' END; INSERT INTO public.circle_members(circle_id,user_id,status) VALUES(cid,u,rule) ON CONFLICT DO NOTHING; IF FOUND THEN INSERT INTO public.events(user_id,circle_id,name) VALUES(u,cid,CASE WHEN rule='pending' THEN 'circle_join_requested' WHEN action='invite_join' THEN 'joined_circle' ELSE 'circle_joined_from_search' END); END IF; RETURN jsonb_build_object('id',cid,'status',rule); END IF;
IF NOT public.is_member(cid) THEN RAISE EXCEPTION 'This circle is private'; END IF;
IF action='leave' THEN IF c.owner_id=u THEN RAISE EXCEPTION 'Hand ownership to another member before leaving'; END IF; target=u;
ELSE IF c.owner_id IS DISTINCT FROM u AND NOT public.is_admin() THEN RAISE EXCEPTION 'Only the circle owner can do this'; END IF; target=(payload->>'user_id')::uuid; END IF;
IF action IN('leave','remove_member') THEN IF target=c.owner_id OR (action='remove_member' AND target=u) THEN RAISE EXCEPTION 'Hand ownership to another member first'; END IF; IF EXISTS(SELECT 1 FROM public.claims cl JOIN public.item_circles ic ON ic.item_id=cl.item_id JOIN public.items i ON i.id=cl.item_id WHERE ic.circle_id=cid AND cl.status IN('claimed','pickup_arranged') AND (cl.receiver_id=target OR i.giver_id=target)) THEN RAISE EXCEPTION 'Finish or expire active pickups before leaving or removing this member'; END IF; DELETE FROM public.circle_members WHERE circle_id=cid AND user_id=target; IF FOUND THEN INSERT INTO public.events(user_id,circle_id,name) VALUES(u,cid,CASE WHEN action='leave' THEN 'circle_left' ELSE 'member_removed' END); END IF;
ELSIF action='approve' THEN UPDATE public.circle_members SET status='active',joined_at=now() WHERE circle_id=cid AND user_id=target AND status='pending'; IF FOUND THEN INSERT INTO public.events(user_id,circle_id,name) VALUES(u,cid,'circle_join_approved'); END IF;
ELSIF action='decline' THEN DELETE FROM public.circle_members WHERE circle_id=cid AND user_id=target AND status='pending';
ELSIF action='transfer' THEN IF NOT EXISTS(SELECT 1 FROM public.circle_members WHERE circle_id=cid AND user_id=target AND status='active') THEN RAISE EXCEPTION 'Choose an active member'; END IF; PERFORM 1 FROM public.profiles WHERE id=target FOR UPDATE; IF (SELECT count(*) FROM public.circles WHERE owner_id=target)>=5 THEN RAISE EXCEPTION 'This member already owns 5 circles'; END IF; UPDATE public.circle_members SET role='member' WHERE circle_id=cid; UPDATE public.circle_members SET role='owner' WHERE circle_id=cid AND user_id=target; UPDATE public.circles SET owner_id=target WHERE id=cid;
ELSIF action='rotate_invite' THEN UPDATE public.circles SET invite_token=gen_random_uuid() WHERE id=cid;
ELSIF action='edit' THEN IF coalesce(payload->>'photo_url','')<>'' AND payload->>'photo_url'<>c.photo_url AND NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='item-photos' AND name=payload->>'photo_url' AND (storage.foldername(name))[1]=u::text) THEN RAISE EXCEPTION 'Upload your own circle photo first'; END IF; UPDATE public.circles SET name=coalesce(payload->>'name',name),type=coalesce(payload->>'type',type),description=coalesce(payload->>'description',description),general_area=coalesce(payload->>'general_area',general_area),photo_url=coalesce(payload->>'photo_url',photo_url),join_rule=coalesce(payload->>'join_rule',join_rule),email_domain=coalesce(payload->>'email_domain',email_domain),members_can_invite=coalesce((payload->>'members_can_invite')::boolean,members_can_invite) WHERE id=cid;
ELSE RAISE EXCEPTION 'Unknown circle action'; END IF; RETURN jsonb_build_object('id',cid); END $$;
REVOKE ALL ON FUNCTION public.circle_action(text,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.circle_action(text,jsonb) TO authenticated;
