REVOKE ALL ON FUNCTION public.passalong_legacy_action(text,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.passalong_legacy_action(text,jsonb) TO service_role;
CREATE OR REPLACE FUNCTION public.passalong_action(action text,payload jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; ids uuid[]; cid uuid; u uuid=auth.uid(); BEGIN IF u IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; IF action='join' THEN RETURN public.circle_action('invite_join',payload); ELSIF action='create_circle' THEN RETURN public.circle_action('create',payload); ELSIF action='profile' THEN UPDATE public.profiles SET bio=coalesce(payload->>'bio',bio),general_area=coalesce(payload->>'general_area',general_area) WHERE id=u; END IF;
IF action='post' THEN ids=CASE WHEN payload ? 'circle_ids' THEN ARRAY(SELECT jsonb_array_elements_text(payload->'circle_ids')::uuid) ELSE ARRAY[(payload->>'circle_id')::uuid] END; IF cardinality(ids)<1 OR cardinality(ids)>30 THEN RAISE EXCEPTION 'Choose at least one circle'; END IF; FOREACH cid IN ARRAY ids LOOP PERFORM 1 FROM public.circles WHERE id=cid FOR SHARE; PERFORM 1 FROM public.circle_members WHERE circle_id=cid AND user_id=u AND status='active' FOR SHARE; IF NOT FOUND THEN RAISE EXCEPTION 'Join every selected circle first'; END IF; END LOOP; IF EXISTS(SELECT 1 FROM public.circles WHERE id=ANY(ids) AND is_test) AND EXISTS(SELECT 1 FROM public.circles WHERE id=ANY(ids) AND NOT is_test) THEN RAISE EXCEPTION 'Keep Test circle posts separate from real circles'; END IF; payload=payload||jsonb_build_object('circle_id',ids[1]); END IF;
result=public.passalong_legacy_action(action,payload); IF action='post' THEN INSERT INTO public.item_circles(item_id,circle_id,position) SELECT (result->>'id')::uuid,id,ordinality::integer-1 FROM unnest(ids) WITH ORDINALITY AS x(id,ordinality) ON CONFLICT(item_id,circle_id) DO UPDATE SET position=excluded.position; END IF; RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.apply_matches(expected bigint,pairs jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v bigint; BEGIN SELECT revision INTO v FROM public.match_revision WHERE id=true FOR UPDATE; IF v IS DISTINCT FROM expected THEN RETURN false; END IF; DELETE FROM public.item_matches m WHERE NOT EXISTS(SELECT 1 FROM jsonb_to_recordset(pairs) AS p(item_id uuid,wish_id uuid,user_id uuid) WHERE p.item_id=m.item_id AND p.wish_id=m.wish_id);
WITH fresh AS(INSERT INTO public.item_matches(item_id,wish_id,user_id) SELECT p.item_id,p.wish_id,p.user_id FROM jsonb_to_recordset(pairs) AS p(item_id uuid,wish_id uuid,user_id uuid) JOIN public.items i ON i.id=p.item_id JOIN public.wishes w ON w.id=p.wish_id AND w.user_id=p.user_id WHERE i.status='available' AND i.expires_at>now() AND i.giver_id<>w.user_id AND EXISTS(SELECT 1 FROM public.circle_members m WHERE m.user_id=w.user_id AND m.circle_id=w.circle_id AND m.status='active') AND EXISTS(SELECT 1 FROM public.item_circles ic JOIN public.circle_members cm ON cm.circle_id=ic.circle_id AND cm.status='active' WHERE ic.item_id=i.id AND cm.user_id=w.user_id) ON CONFLICT DO NOTHING RETURNING *) INSERT INTO public.events(user_id,item_id,circle_id,name) SELECT f.user_id,f.item_id,i.circle_id,'match_created' FROM fresh f JOIN public.items i ON i.id=f.item_id; UPDATE public.match_revision SET applied=expected WHERE id=true; RETURN true; END $$;
