ALTER POLICY read_own_or_circle_item_photo ON storage.objects USING(bucket_id='item-photos' AND ((storage.foldername(name))[1]=auth.uid()::text OR EXISTS(SELECT 1 FROM public.items i WHERE i.photo_path=objects.name AND public.has_item_access(i.id))));
COMMENT ON COLUMN public.items.circle_id IS 'Compatibility primary circle: first selected circle for safe item previews and event attribution; inventory visibility uses item_circles';
COMMENT ON COLUMN public.circles.required_email_domain IS 'Existing protected circle eligibility; new circles use email_domain';